AA,CACA,yBAAA,CACA,YAAA,CAGF,uDACE,yBAAA,CACA,eAAA,CAGF,0CACE,WAAA,CACA,UAAA,CAGF,+BACE,cAAA,CAGF,gCACE,UAAA,CACA,WAAA,CACA,qCAAA,CACA,qBAAA,CACA,iBAAA,CACA,2CAAA,CAGF,gCACE,SAAA,CAGF,6BACE,YAAA,CACA,kBAAA,CACA,OAAA,CACA,eAAA,CACA,iBAAA,CACA,sCAAA,CACA,2BAAA,CACA,gCAAA,CACA,0BAAA,CACA,cAAA,CACA,gBAAA,CAGF,kCACE,YAAA,CACA,kBAAA,CACA,aAAA,CACA,UAAA,CACA,WAAA,CACA,6BAAA,CACA,iBAAA,CACA,cAAA,CACA,eAAA,CAKF,+BACE,iBAAA,CACA,iBAAA,CAGF,gCACE,YAAA,CACA,kBAAA,CACA,UAAA,CACA,WAAA,CACA,kBAAA,CACA,QAAA,CACA,iBAAA,CACA,yBAAA,CACA,UAAA,CACA,cAAA,CAGF,kCACE,cAAA,CAGF,mEACE,cAAA,CACA,kBAAA,CACA,yBAAA,CACA,cAAA,CACA,gBAAA,CAGF,8BACE,YAAA,CACA,kBAAA,CACA,QAAA,CACA,eAAA,CACA,kBAAA,CACA,yBAAA,CACA,cAAA,CAGF,6FAEE,MAAA,CACA,UAAA,CACA,yBAAA,CAGF,gCACE,eAAA,CACA,sBAAA,CACA,cAAA,CAGF,iCACE,YAAA,CACA,sBAAA,CACA,cAAA,CACA,QAAA,CACA,gBAAA,CACA,yBAAA,CACA,eAAA,CACA,eAAA,CACA,iBAAA,CAKF,oCACE,oGACE,CAIJ,oCACE,kDACE,CAIJ,kCACE,SAAA,CACA,2BAAA,CAGF,gCACE,SAAA,CACA,2BAAA,CAIF,sCACE,sEAAA,CAGF,mDACE,oBAAA,CAGF,mDACE,oBAAA,CAGF,wGAEE,oBAAA,CAGF,+BACE,KACE,SAAA,CACA,yBAAA,CAGF,GACE,SAAA,CACA,cAAA,CAAA,CAIJ,yBACE,GACE,wBAAA,CAAA,CAMJ,yBACE,gCACE,sBAAA,CAGF,iCACE,sBAAA,CACA,aAAA,CAGF,6BACE,YAAA,CAGF,oBACE,cAAA,CAGF,6BACE,sBAAA,CAGF,qEAEE,cAAA,CAGF,2DAEE,yBAAA,CAGF,+CACE,eAAA,CAGF,0BACE,eAAA,CAGF,4BACE,aAAA,CACA,cAAA,CAGF,6BACE,YAAA,CAGF,+BACE,eAAA,CAGF,uCACE,6CAAA,CAGF,8FAEE,kBAAA,CAGF,gCACE,aAAA,CAAA,CAIJ,uCACE,qEAGE,mCAAA,CACA,6BAAA,CACA,sCAAA,CACA,+BAAA,CACA,oCAAA,CACA,8BAAA,CAAA","sourcesContent":["/* form-base.scss — 开局表单（花信 · 关系档案感）\n *\n * 版面语言：大圆角面板、花色圆点步骤条、圆角输入框、花色渐变按钮。\n * 像填一份温柔的关系档案。\n *\n * 验收信号（改样式时不要动）：\n *   .stepper 是 display:flex、.form-panel 内边距 28px 30px 20px、.field 是 display:flex\n *   .page-enter-active 260ms / .page-leave-active 140ms / .page-enter-from 带 clip-path\n */\n\n/* ── 令牌：浅色暖米粉为默认，深色偏好时翻成暮紫 ───────────────── */\n\n.opening-shell {\n  --fq-bg: #faf5f2;\n  --fq-bg-grad: linear-gradient(180deg, #faf5f2, #f3ebe8);\n  --fq-panel: #fffaf8;\n  --fq-panel-2: #f5ede9;\n  --fq-ink: #3d2d33;\n  --fq-ink-soft: #5c4450;\n  --fq-ink-faint: #8c6e78;\n  --fq-line: rgba(61, 45, 51, 0.14);\n  --fq-rule: rgba(61, 45, 51, 0.08);\n  --fq-hairline: rgba(61, 45, 51, 0.06);\n  --fq-accent: #d6427a;\n  --fq-accent-light: #ff6097;\n  --fq-accent-ink: #b05878;\n  --fq-fill: linear-gradient(135deg, #ff6097, #d6427a);\n  --fq-fill-solid: #d6427a;\n  --fq-accent-wash: rgba(214, 66, 122, 0.10);\n  --fq-ok: #6b8a6f;\n  --fq-violet: #7b53c9;\n  --fq-soft: 0 2px 12px rgba(61, 45, 51, 0.10);\n  --fq-soft-sm: 0 1px 6px rgba(61, 45, 51, 0.08);\n  --fq-sans: 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', system-ui, sans-serif;\n\n  position: relative;\n  isolation: isolate;\n  width: min(100%, 820px);\n  min-height: 100vh;\n  margin: 0 auto;\n  padding: 34px 26px 26px;\n  background: var(--fq-bg-grad);\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n}\n\n@media (prefers-color-scheme: dark) {\n  .opening-shell {\n    --fq-bg: #1c151f;\n    --fq-bg-grad: linear-gradient(180deg, #241a28, #1c151f);\n    --fq-panel: #2a2238;\n    --fq-panel-2: #241d30;\n    --fq-ink: #f5ece8;\n    --fq-ink-soft: #d4bec8;\n    --fq-ink-faint: #9a8492;\n    --fq-line: rgba(245, 236, 232, 0.12);\n    --fq-rule: rgba(245, 236, 232, 0.07);\n    --fq-hairline: rgba(245, 236, 232, 0.05);\n    --fq-accent: #ff6097;\n    --fq-accent-light: #f0b8cc;\n    --fq-accent-ink: #f0b8cc;\n    --fq-fill: linear-gradient(135deg, #ff6097, #d6427a);\n    --fq-fill-solid: #d6427a;\n    --fq-accent-wash: rgba(255, 96, 151, 0.14);\n    --fq-ok: #4fd6c0;\n    --fq-violet: #9d4edd;\n    --fq-soft: 0 2px 12px rgba(0, 0, 0, 0.22);\n    --fq-soft-sm: 0 1px 6px rgba(0, 0, 0, 0.16);\n  }\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n}\n\nbutton {\n  cursor: pointer;\n}\n\nh1,\nh2,\nh3,\np {\n  overflow-wrap: anywhere;\n}\n\n.ambient,\n.ornament-top {\n  display: none;\n}\n\n/* ── 刊头 ───────────────────────────────────────────────────────────── */\n\n.opening-header {\n  display: flex;\n  align-items: flex-start;\n  gap: 16px;\n  min-width: 0;\n  padding: 0 0 18px;\n  border-bottom: 1px solid var(--fq-line);\n}\n\n/* 花色渐变圆角品牌标记 */\n.brand-mark {\n  position: relative;\n  flex: 0 0 46px;\n  width: 46px;\n  height: 46px;\n  border-radius: 14px;\n  background: var(--fq-fill);\n  color: #fff;\n\n  &::after {\n    content: '✿';\n    position: absolute;\n    inset: 0;\n    display: grid;\n    place-items: center;\n    font-size: 20px;\n  }\n\n  .brand-star,\n  .brand-ring,\n  .brand-heart {\n    display: none;\n  }\n}\n\n.brand-copy {\n  min-width: 0;\n}\n\n.eyebrow {\n  margin: 0 0 6px;\n  color: var(--fq-accent);\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  line-height: 1.4;\n}\n\nh1 {\n  margin: 0;\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n  font-size: 36px;\n  font-weight: 700;\n  line-height: 1.1;\n  letter-spacing: -0.01em;\n}\n\n.subtitle {\n  margin: 8px 0 0;\n  max-width: 44ch;\n  color: var(--fq-ink-faint);\n  font-size: 12.5px;\n  line-height: 1.7;\n}\n\n.world-note {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  margin-left: auto;\n  padding: 4px 0 0;\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  line-height: 1.3;\n  white-space: nowrap;\n}\n\n.note-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--fq-accent);\n}\n\n/* ── 步骤条：花色圆点 + 连接线 ─────────────────────────────────────── */\n\n.stepper {\n  display: flex;\n  gap: 0;\n  margin: 0;\n  padding: 0;\n  background: transparent;\n  overflow: visible;\n}\n\n.step-item {\n  display: flex;\n  flex: 1 1 0;\n  align-items: center;\n  justify-content: flex-start;\n  gap: 8px;\n  min-width: 0;\n  min-height: 46px;\n  padding: 10px 12px 11px;\n  border: 0;\n  background: transparent;\n  color: var(--fq-ink-faint);\n  font-size: 12px;\n  position: relative;\n  transition: color 0.18s ease;\n\n  /* 连接线：花色渐变 */\n  &::after {\n    content: '';\n    position: absolute;\n    right: -4px;\n    top: 50%;\n    transform: translateY(-50%);\n    width: 8px;\n    height: 2px;\n    background: linear-gradient(90deg, var(--fq-accent-faint, var(--fq-accent-wash)), transparent);\n    border-radius: 1px;\n    z-index: 0;\n  }\n\n  &:last-child::after { display: none; }\n\n  &:hover,\n  &:focus-visible {\n    color: var(--fq-ink-soft);\n    outline: none;\n  }\n\n  &.active {\n    color: var(--fq-accent);\n    font-weight: 600;\n  }\n\n  &.done {\n    color: var(--fq-ink-soft);\n  }\n}\n\n/* 步骤圆点 */\n.step-number {\n  flex: 0 0 auto;\n  display: grid;\n  place-items: center;\n  width: 22px;\n  height: 22px;\n  border-radius: 50%;\n  font-size: 10px;\n  font-weight: 700;\n  border: 2px solid var(--fq-line);\n  background: transparent;\n  color: var(--fq-ink-faint);\n  padding: 0;\n  transition: all 0.22s ease;\n  position: relative;\n  z-index: 1;\n}\n\n/* 当前步骤：花色实心大圆点 */\n.step-item.active .step-number {\n  border-color: var(--fq-accent);\n  background: var(--fq-accent);\n  color: #fff;\n  transform: scale(1.1);\n  box-shadow: 0 0 0 4px var(--fq-accent-wash);\n}\n\n/* 完成步骤：花色对号圆点 */\n.step-item.done .step-number {\n  border-color: var(--fq-accent);\n  background: var(--fq-accent);\n  color: #fff;\n\n  &::after {\n    content: '✓';\n    position: absolute;\n    inset: 0;\n    display: grid;\n    place-items: center;\n    font-size: 10px;\n    font-weight: 700;\n    color: #fff;\n  }\n}\n\n.step-label {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-weight: 500;\n}\n\n.step-item.active .step-label {\n  color: var(--fq-accent);\n  font-weight: 600;\n}\n\n/* ── 问卷面板 ───────────────────────────────────────────────────────── */\n\n.form-panel,\n.locked-panel {\n  position: relative;\n  border: 1px solid var(--fq-line);\n  background: var(--fq-panel);\n  box-shadow: var(--fq-soft);\n  border-radius: 20px;\n}\n\n.form-panel {\n  padding: 28px 30px 20px;\n  /* 顶部花色渐变细条 */\n  &::before {\n    content: '';\n    position: absolute;\n    top: 0;\n    left: 0;\n    right: 0;\n    height: 3px;\n    background: var(--fq-fill);\n    border-radius: 20px 20px 0 0;\n  }\n}\n\n.panel-heading {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 20px;\n  padding-bottom: 16px;\n  border-bottom: 1px solid var(--fq-line);\n}\n\n.panel-heading h2,\n.locked-panel h2 {\n  margin: 0;\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n  font-size: 26px;\n  font-weight: 700;\n  line-height: 1.2;\n}\n\n.heading-description {\n  max-width: 46ch;\n  margin: 10px 0 0;\n  color: var(--fq-ink-faint);\n  font-size: 12.5px;\n  line-height: 1.7;\n}\n\n/* 页码读数 */\n.page-count {\n  flex: 0 0 auto;\n  display: flex;\n  align-items: baseline;\n  gap: 4px;\n  padding: 0;\n  border: 0;\n  color: var(--fq-ink-faint);\n  white-space: nowrap;\n}\n\n.page-count strong {\n  color: var(--fq-accent);\n  font-size: 26px;\n  font-weight: 700;\n  line-height: 1;\n  font-variant-numeric: tabular-nums;\n}\n\n.page-count span {\n  font-size: 11px;\n}\n\n.step-content {\n  min-height: 430px;\n  padding-top: 22px;\n  clip-path: inset(0);\n}\n\n/* 段落导语 */\n.section-intro {\n  display: flex;\n  align-items: baseline;\n  gap: 14px;\n  margin-bottom: 26px;\n  padding-bottom: 12px;\n  border-bottom: 1px solid var(--fq-hairline);\n  color: var(--fq-ink-soft);\n  font-size: 12.5px;\n  line-height: 1.7;\n}\n\n.section-intro p {\n  max-width: 54ch;\n  margin: 0;\n}\n\n.section-symbol {\n  flex: 0 0 auto;\n  width: auto;\n  height: auto;\n  border: 0;\n  border-radius: 0;\n  color: var(--fq-accent);\n  font-size: 20px;\n  font-weight: 600;\n  line-height: 0.9;\n}\n\n/* ── 字段 ───────────────────────────────────────────────────────────── */\n\n.field-grid {\n  display: grid;\n  gap: 18px;\n}\n\n.two-columns {\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  column-gap: 26px;\n}\n\n.two-columns > *:nth-child(odd) {\n  padding-right: 26px;\n}\n\n.two-columns > *:nth-child(even) {\n  padding-right: 0;\n}\n\n.field,\n.static-field {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  gap: 4px;\n}\n\n/* 字段标签：花色小号 */\n.field > span,\n.static-field > span {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  color: var(--fq-accent);\n  font-size: 11px;\n  font-weight: 600;\n}\n\n.field b {\n  color: var(--fq-accent);\n  font-weight: 700;\n  font-size: 11px;\n}\n\n.field em {\n  margin-left: 5px;\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  font-style: normal;\n  font-weight: 400;\n}\n\n/* 圆角输入框，聚焦时花色柔光边框 */\n.field input,\n.field select,\n.field textarea {\n  width: 100%;\n  min-width: 0;\n  border: 1.5px solid var(--fq-line);\n  border-radius: 12px;\n  background: var(--fq-panel);\n  color: var(--fq-ink);\n  font-size: 14px;\n  line-height: 1.5;\n  outline: none;\n  box-shadow: none;\n  transition: border-color 0.22s ease, box-shadow 0.22s ease;\n}\n\n.field input,\n.field select {\n  min-height: 38px;\n  padding: 7px 12px;\n}\n\n.field textarea {\n  min-height: 82px;\n  resize: vertical;\n  padding: 8px 12px;\n}\n\n.field input::placeholder,\n.field textarea::placeholder {\n  color: var(--fq-ink-faint);\n  opacity: 0.7;\n}\n\n.field input:focus,\n.field select:focus,\n.field textarea:focus {\n  border-color: var(--fq-accent);\n  box-shadow: 0 0 0 3px var(--fq-accent-wash);\n}\n\n.field small,\n.static-field small {\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  font-weight: 400;\n  line-height: 1.6;\n}\n\n.field-count {\n  align-self: flex-end;\n  margin-top: 2px;\n  font-size: 10px;\n  font-variant-numeric: tabular-nums;\n}\n\n.identity-row {\n  margin-top: 18px;\n}\n\n/* 只读格：花色左边框 */\n.static-field {\n  justify-content: center;\n  min-height: 78px;\n  padding: 8px 0 8px 14px;\n  border-left: 3px solid var(--fq-accent);\n  background: var(--fq-accent-wash);\n  border-radius: 0 12px 12px 0;\n}\n\n.static-field strong {\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n  font-size: 16px;\n  font-weight: 700;\n